# Create a comprehensive mempalace application script
mempalace_script = f"""
# MemPalace Application for All Book Projects
# Generated on {datetime.now().isoformat()}

import os
import json
from datetime import datetime

def initialize_mempalace():
    \"\"\"Initialize the MemPalace system with default configuration.\"\"\"
    config = {
        'palaces': {},
        'embedding_model': 'text-embedding-ada-002',
        'faiss_index': None,
        'data_dir': './mempalace_data',
        'backup_dir': './mempalace_backups'
    }
    return config

def create_palace(config, name, description):
    \"\"\"Create a new memory palace.\"\"\"
    palace_id = name.lower().replace(' ', '_')
    config['palaces'][palace_id] = {
        'name': name,
        'description': description,
        'rooms': {}
    }
    return palace_id

def create_room(config, palace_id, name, description):
    \"\"\"Create a new room within a palace.\"\"\"
    room_id = name.lower().replace(' ', '_')
    config['palaces'][palace_id]['rooms'][room_id] = {
        'name': name,
        'description': description,
        'locations': {}
    }
    return room_id

def add_memory_location(config, palace_id, room_id, name, image_path, note, tags=None):
    \"\"\"Add a new memory location with image and note.\"\"\"
    location_id = name.lower().replace(' ', '_')
    timestamp = datetime.now().isoformat()

    location = {
        'name': name,
        'image': image_path,
        'note': note,
        'tags': tags or [],
        'timestamp': timestamp,
        'score': 0.8
    }

    config['palaces'][palace_id]['rooms'][room_id]['locations'][location_id] = location

    return location_id

# Initialize MemPalace
config = initialize_mempalace()

# Apply to book projects
book_projects = [
    {{
        'title': 'The Unwritten Future',
        'description': 'Memoir project with lunar village cover',
        'chapters': {{
            'Chapter 1': 'Shock and beginning',
            'Chapter 2': 'Mr. Chips and family legacy',
            'Chapter 3': 'Echoes of Sputnik',
            'Chapter 4': 'The Garage',
            'Chapter 5': 'The Spark Ignites',
            'Chapter 6': 'Life as an Engineer',
            'Chapter 7': 'Foundations',
            'Chapter 8': 'The Diagnosis',
            'Chapter 9': 'The New Partnership',
            'Chapter 10': 'The Y2K Challenge',
            'Chapter 11': 'The New Beginning',
            'Chapter 12': 'The Evolution'
        }}
    }},
    {{
        'title': 'First Generation',
        'description': 'Hard sci-fi novel',
        'chapters': {{
            'Prologue': 'Introduction to the world',
            'Chapter 1': 'The discovery',
            'Chapter 2': 'The conflict',
            'Chapter 3': 'The journey',
            'Chapter 4': 'The revelation'
        }}
    }},
    {{
        'title': 'Second Generation',
        'description': 'Sequel to First Generation',
        'chapters': {{
            'Prologue': 'Continuing the story',
            'Chapter 1': 'The aftermath',
            'Chapter 2': 'New threats',
            'Chapter 3': 'Old enemies',
            'Chapter 4': 'The final battle'
        }}
    }},
    {{
        'title': 'Small Business AI Book',
        'description': 'Guide for small businesses',
        'chapters': {{
            'Introduction': 'AI for small businesses',
            'Chapter 1': 'Understanding AI',
            'Chapter 2': 'Implementation strategies',
            'Chapter 3': 'Tools and resources',
            'Chapter 4': 'Case studies',
            'Chapter 5': 'Future trends'
        }}
    }}
]

# Create palaces for each book
for project in book_projects:
    palace_id = create_palace(config, project['title'], project['description'])

    # Create rooms for parts/chapters
    for part_title, chapters in project['chapters'].items():
        if 'Chapter' in part_title or 'Prologue' in part_title:
            room_id = create_room(config, palace_id, part_title, f"Section: {part_title}")

            # Add memory locations for each chapter
            for chapter_num, chapter_content in enumerate(project['chapters'].items(), 1):
                if chapter_num <= 12:  # Assuming 12 chapters max
                    location_name = f"Chapter {chapter_num}"
                    image_path = f"generated_images/chapter{chapter_num}.png"
                    note = f"Chapter {chapter_num} content summary"
                    add_memory_location(
                        config, palace_id, room_id, 
                        location_name, image_path, note,
                        tags=["book", "chapter", "writing"]
                    )

# Save configuration
if not os.path.exists('mempalace_data'):
    os.makedirs('mempalace_data')

with open('mempalace_data/config.json', 'w') as f:
    json.dump(config, f, indent=2)

print(f"✅ MemPalace initialized for {len(book_projects)} book projects")
print(f"📊 Total palaces created: {len(config['palaces'])}")

# Send notification
print("🧠 MemPalace application complete!")
"""

with open('/home/bob/books/The_Unwritten_Future/mempalace_application.py', 'w') as f:
