        for i, ctx in enumerate(chapters[chapter_num]['context']):
            print(f"    {i+1}. {ctx}")
    else:
        print("  (No additional context available)")

# Check current image placement
print("\n" + "="*80)
print("Current Image Placement:")
print("="*80)
for chapter_num in sorted(chapters.keys()):
    has_image = False
    image_alt = ""

