            has_image = True
            image_alt = next_img.get('alt', '').strip()

    status = "✅ Has image" if has_image else "❌ No image"
    print(f"{status}: Chapter {chapter_num} - {chapters[chapter_num]['title']}")
    if has_image:
        print(f"       Alt text: '{image_alt}'")"}

